- 	ret = cros_ec_get_cmd_versions(cros_ec, EC_CMD_CHARGE_CONTROL);
- 	if (ret < 0)
- 		return ret;
-@@ -327,7 +344,8 @@ static int cros_chctl_probe(struct platform_device *pdev)
